  logic [PARA_U2_HC_IEN_COUNT-1:0] w_u2_hc_ien_stall_nxt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] reg_u2_hc_ien_nyet;
  logic [PARA_U2_HC_IEN_COUNT-1:0] w_u2_hc_ien_nyet_nxt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] reg_u2_hc_ien_nak;
  logic [PARA_U2_HC_IEN_COUNT-1:0] w_u2_hc_ien_nak_nxt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] reg_u2_hc_ien_timeout;
  logic [PARA_U2_HC_IEN_COUNT-1:0] w_u2_hc_ien_timeout_nxt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] reg_u2_hc_ien_ch_halt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] w_u2_hc_ien_ch_halt_nxt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] reg_u2_hc_ien_done;
  logic [PARA_U2_HC_IEN_COUNT-1:0] w_u2_hc_ien_done_nxt;
  logic [PARA_U2_HC_IEN_COUNT-1:0] w_we_u2_hc_ien;
  logic [PARA_U2_HC_IEN_COUNT-1:0][LPARA_DATA_W-1:0] w_u2_hc_ien_value;
  logic [PARA_U2_HC_CFG_COUNT-1:0][15:0] reg_u2_hc_cfg_interval;
  logic [PARA_U2_HC_CFG_COUNT-1:0][15:0] w_u2_hc_cfg_interval_nxt;
  logic [PARA_U2_HC_CFG_COUNT-1:0] reg_u2_hc_cfg_poll_rep;
  logic [PARA_U2_HC_CFG_COUNT-1:0] w_u2_hc_cfg_poll_rep_nxt;
  logic [PARA_U2_HC_CFG_COUNT-1:0] reg_u2_hc_cfg_poll_en;
  logic [PARA_U2_HC_CFG_COUNT-1:0] w_u2_hc_cfg_poll_en_nxt;
  logic [PARA_U2_HC_CFG_COUNT-1:0] reg_u2_hc_cfg_short_end;
  logic [PARA_U2_HC_CFG_COUNT-1:0] w_u2_hc_cfg_short_end_nxt;
  logic [PARA_U2_HC_CFG_COUNT-1:0] reg_u2_hc_cfg_zlp_en;
  logic [PARA_U2_HC_CFG_COUNT-1:0] w_u2_hc_cfg_zlp_en_nxt;
  logic [PARA_U2_HC_CFG_COUNT-1:0] reg_u2_hc_cfg_dbuf;
  logic [PARA_U2_HC_CFG_COUNT-1:0] w_u2_hc_cfg_dbuf_nxt;
  logic [PARA_U2_HC_CFG_COUNT-1:0] w_we_u2_hc_cfg;
  logic [PARA_U2_HC_CFG_COUNT-1:0][LPARA_DATA_W-1:0] w_u2_hc_cfg_value;

  // The parameter selects the register clock/reset for the chosen bus front end.
  assign w_clk_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;


  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // i_slverr_en enables error responses. When disabled, PSTRB still selects the bytes written.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en & (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb[LPARA_STRB_W-1:0] & i_apb_pwrite));

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Capture PSTRB independently of i_slverr_en; it always masks the bytes updated by a write.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wstrb
    if (!i_rst_n_apb)
      reg_wstrb <= '0;
    else if (w_apb_wr)
      reg_wstrb <= i_apb_pstrb[LPARA_STRB_W-1:0];
  end
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_apb_wmask
      assign w_wmask[(gen_lane * 8) +: 8] = {8{reg_wstrb[gen_lane]}};
    end
  endgenerate

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_u2_ctrl = w_wr_en & (reg_addr == LPARA_U2_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_irq_raw = w_wr_en & (reg_addr == LPARA_U2_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_irq_en = w_wr_en & (reg_addr == LPARA_U2_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_irq_inj = w_wr_en & (reg_addr == LPARA_U2_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_dctrl = w_wr_en & (reg_addr == LPARA_U2_DCTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_hport = w_wr_en & (reg_addr == LPARA_U2_HPORT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_hsts = w_wr_en & (reg_addr == LPARA_U2_HSTS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_sof_cfg = w_wr_en & (reg_addr == LPARA_U2_SOF_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_dma_cfg = w_wr_en & (reg_addr == LPARA_U2_DMA_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_dma_hi = w_wr_en & (reg_addr == LPARA_U2_DMA_HI_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_phy_acc = w_wr_en & (reg_addr == LPARA_U2_PHY_ACC_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_fifo_rx = w_wr_en & (reg_addr == LPARA_U2_FIFO_RX_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_fifo_hnp = w_wr_en & (reg_addr == LPARA_U2_FIFO_HNP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_fifo_hpt = w_wr_en & (reg_addr == LPARA_U2_FIFO_HPT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_fifo_ctl = w_wr_en & (reg_addr == LPARA_U2_FIFO_CTL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_lpm_cfg = w_wr_en & (reg_addr == LPARA_U2_LPM_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_lpbk_sts = w_wr_en & (reg_addr == LPARA_U2_LPBK_STS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_dma_wbase = w_wr_en & (reg_addr == LPARA_U2_DMA_WBASE_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_u2_dma_wlim = w_wr_en & (reg_addr == LPARA_U2_DMA_WLIM_OFFSET[LPARA_ADDR_W-1:0]);
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_DMA_MAP_COUNT) && (gen_idx < LPARA_U2_DMA_MAP_MAX_COUNT); gen_idx++) begin : gen_u2_dma_map_we_decode
    assign w_we_u2_dma_map[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_DMA_MAP_BASE_OFFSET + (gen_idx * LPARA_U2_DMA_MAP_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPI_CTL_COUNT) && (gen_idx < LPARA_U2_EPI_CTL_MAX_COUNT); gen_idx++) begin : gen_u2_epi_ctl_we_decode
    assign w_we_u2_epi_ctl[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPI_CTL_BASE_OFFSET + (gen_idx * LPARA_U2_EPI_CTL_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPI_XFR_COUNT) && (gen_idx < LPARA_U2_EPI_XFR_MAX_COUNT); gen_idx++) begin : gen_u2_epi_xfr_we_decode
    assign w_we_u2_epi_xfr[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPI_XFR_BASE_OFFSET + (gen_idx * LPARA_U2_EPI_XFR_OFFSET_STRIDE)));
