  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPI_DMA_COUNT) && (gen_idx < LPARA_U2_EPI_DMA_MAX_COUNT); gen_idx++) begin : gen_u2_epi_dma_we_decode
    assign w_we_u2_epi_dma[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPI_DMA_BASE_OFFSET + (gen_idx * LPARA_U2_EPI_DMA_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPI_BUF_COUNT) && (gen_idx < LPARA_U2_EPI_BUF_MAX_COUNT); gen_idx++) begin : gen_u2_epi_buf_we_decode
    assign w_we_u2_epi_buf[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPI_BUF_BASE_OFFSET + (gen_idx * LPARA_U2_EPI_BUF_OFFSET_STRIDE)));
