    assign w_we_u2_epi_int[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPI_INT_BASE_OFFSET + (gen_idx * LPARA_U2_EPI_INT_OFFSET_STRIDE)));
