    assign w_we_u2_epi_ien[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPI_IEN_BASE_OFFSET + (gen_idx * LPARA_U2_EPI_IEN_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPO_CTL_COUNT) && (gen_idx < LPARA_U2_EPO_CTL_MAX_COUNT); gen_idx++) begin : gen_u2_epo_ctl_we_decode
    assign w_we_u2_epo_ctl[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPO_CTL_BASE_OFFSET + (gen_idx * LPARA_U2_EPO_CTL_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPO_XFR_COUNT) && (gen_idx < LPARA_U2_EPO_XFR_MAX_COUNT); gen_idx++) begin : gen_u2_epo_xfr_we_decode
    assign w_we_u2_epo_xfr[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPO_XFR_BASE_OFFSET + (gen_idx * LPARA_U2_EPO_XFR_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPO_DMA_COUNT) && (gen_idx < LPARA_U2_EPO_DMA_MAX_COUNT); gen_idx++) begin : gen_u2_epo_dma_we_decode
    assign w_we_u2_epo_dma[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPO_DMA_BASE_OFFSET + (gen_idx * LPARA_U2_EPO_DMA_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPO_INT_COUNT) && (gen_idx < LPARA_U2_EPO_INT_MAX_COUNT); gen_idx++) begin : gen_u2_epo_int_we_decode
    assign w_we_u2_epo_int[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPO_INT_BASE_OFFSET + (gen_idx * LPARA_U2_EPO_INT_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_EPO_IEN_COUNT) && (gen_idx < LPARA_U2_EPO_IEN_MAX_COUNT); gen_idx++) begin : gen_u2_epo_ien_we_decode
    assign w_we_u2_epo_ien[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_EPO_IEN_BASE_OFFSET + (gen_idx * LPARA_U2_EPO_IEN_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_CTRL_COUNT) && (gen_idx < LPARA_U2_HC_CTRL_MAX_COUNT); gen_idx++) begin : gen_u2_hc_ctrl_we_decode
    assign w_we_u2_hc_ctrl[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_CTRL_BASE_OFFSET + (gen_idx * LPARA_U2_HC_CTRL_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_SPL_COUNT) && (gen_idx < LPARA_U2_HC_SPL_MAX_COUNT); gen_idx++) begin : gen_u2_hc_spl_we_decode
    assign w_we_u2_hc_spl[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_SPL_BASE_OFFSET + (gen_idx * LPARA_U2_HC_SPL_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_XFER_COUNT) && (gen_idx < LPARA_U2_HC_XFER_MAX_COUNT); gen_idx++) begin : gen_u2_hc_xfer_we_decode
    assign w_we_u2_hc_xfer[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_XFER_BASE_OFFSET + (gen_idx * LPARA_U2_HC_XFER_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_DMA_COUNT) && (gen_idx < LPARA_U2_HC_DMA_MAX_COUNT); gen_idx++) begin : gen_u2_hc_dma_we_decode
    assign w_we_u2_hc_dma[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_DMA_BASE_OFFSET + (gen_idx * LPARA_U2_HC_DMA_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_INT_COUNT) && (gen_idx < LPARA_U2_HC_INT_MAX_COUNT); gen_idx++) begin : gen_u2_hc_int_we_decode
    assign w_we_u2_hc_int[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_INT_BASE_OFFSET + (gen_idx * LPARA_U2_HC_INT_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_IEN_COUNT) && (gen_idx < LPARA_U2_HC_IEN_MAX_COUNT); gen_idx++) begin : gen_u2_hc_ien_we_decode
    assign w_we_u2_hc_ien[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_IEN_BASE_OFFSET + (gen_idx * LPARA_U2_HC_IEN_OFFSET_STRIDE)));
  end
  endgenerate
  // Decode a software write independently for every generated register index.
  generate
  for (genvar gen_idx = 0; (gen_idx < PARA_U2_HC_CFG_COUNT) && (gen_idx < LPARA_U2_HC_CFG_MAX_COUNT); gen_idx++) begin : gen_u2_hc_cfg_we_decode
    assign w_we_u2_hc_cfg[gen_idx] = w_wr_en & (32'(reg_addr) == (LPARA_U2_HC_CFG_BASE_OFFSET + (gen_idx * LPARA_U2_HC_CFG_OFFSET_STRIDE)));
  end
  endgenerate

  // Register transaction events are qualified by the captured APB transfer.
  // Read events include aligned unmapped reads, which return zero. Unaligned reads
  // are suppressed even when the APB error response is disabled.
  assign o_reg_rd_en   = w_rd_en & (reg_addr[1:0] == 2'b0);
  assign o_reg_rd_addr = o_reg_rd_en ? reg_addr : '0;

  // Write events are asserted only for a mapped register with at least one
  // software-writable field; rejected and read-only writes do not assert this event.
  assign o_reg_wr_en   =
    (|w_we_u2_ctrl)
    | (|w_we_u2_irq_raw)
    | (|w_we_u2_irq_en)
    | (|w_we_u2_irq_inj)
    | (|w_we_u2_dctrl)
    | (|w_we_u2_hport)
    | (|w_we_u2_hsts)
    | (|w_we_u2_sof_cfg)
    | (|w_we_u2_dma_cfg)
    | (|w_we_u2_dma_hi)
    | (|w_we_u2_phy_acc)
    | (|w_we_u2_fifo_rx)
    | (|w_we_u2_fifo_hnp)
    | (|w_we_u2_fifo_hpt)
    | (|w_we_u2_fifo_ctl)
    | (|w_we_u2_lpm_cfg)
    | (|w_we_u2_lpbk_sts)
    | (|w_we_u2_dma_wbase)
    | (|w_we_u2_dma_wlim)
    | (|w_we_u2_dma_map)
    | (|w_we_u2_epi_ctl)
    | (|w_we_u2_epi_xfr)
    | (|w_we_u2_epi_dma)
    | (|w_we_u2_epi_buf)
    | (|w_we_u2_epi_int)
    | (|w_we_u2_epi_ien)
    | (|w_we_u2_epo_ctl)
    | (|w_we_u2_epo_xfr)
    | (|w_we_u2_epo_dma)
    | (|w_we_u2_epo_int)
    | (|w_we_u2_epo_ien)
    | (|w_we_u2_hc_ctrl)
    | (|w_we_u2_hc_spl)
    | (|w_we_u2_hc_xfer)
    | (|w_we_u2_hc_dma)
    | (|w_we_u2_hc_int)
    | (|w_we_u2_hc_ien)
    | (|w_we_u2_hc_cfg);
  assign o_reg_wr_addr = o_reg_wr_en ? reg_addr : '0;

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_rd_req),
        .o_q         (w_rd_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
        if (!i_rst_n_reg)
          reg_rd_req_reg_dly <= 1'b0;
        else
          reg_rd_req_reg_dly <= w_rd_req_reg;
      end
      assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
      assign w_rd_ack = reg_rd_req_reg_dly;

      // Write request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_req_sync (
        .i_clk_dst   (i_clk_reg),
        .i_rst_n_dst (i_rst_n_reg),
        .i_d         (reg_wr_req),
        .o_q         (w_wr_req_reg)
      );
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
        if (!i_rst_n_reg)
          reg_wr_req_reg_dly <= 1'b0;
        else
          reg_wr_req_reg_dly <= w_wr_req_reg;
      end
      assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
      assign w_wr_ack = reg_wr_req_reg_dly;

      // PREADY pulses after an acknowledged operation or a SETUP-phase error.
      assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end else begin : g_sync_csr

      // Synchronous-only request capture and response state.
      logic reg_rd_capture;
      logic reg_wr_capture;
      logic w_pready_nxt;
      logic reg_pready;

      // Read/write enables are delayed one cycle in synchronous mode.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_capture
        if (!i_rst_n_apb) begin
          reg_rd_capture <= 1'b0;
          reg_wr_capture <= 1'b0;
        end else begin
          reg_rd_capture <= w_apb_rd;
          reg_wr_capture <= w_apb_wr;
        end
      end
      assign w_rd_en = reg_rd_capture;
      assign w_wr_en = reg_wr_capture;
      assign w_rd_ack_fall = 1'b0;

      // PREADY pulses after an operation or a SETUP-phase error.
      assign w_pready_nxt = w_wr_en | w_rd_en | (w_apb_slverr & w_apb_setup);
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
        if (!i_rst_n_apb)
          reg_pready <= 1'b0;
        else
          reg_pready <= w_pready_nxt;
      end
      assign o_apb_pready = reg_pready;

    end
  endgenerate

  // Register u2_version: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_u2_version_value
    w_u2_version_value = '0;
    w_u2_version_value[31:16] = i_u2_version_major;
    w_u2_version_value[15:0] = i_u2_version_minor;
  end

  // u2_ctrl_lpbk next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_lpbk_nxt = (w_we_u2_ctrl & (|w_wmask[7])) ? ((reg_wdata[7] & w_wmask[7]) | (reg_u2_ctrl_lpbk & ~w_wmask[7])) : reg_u2_ctrl_lpbk;

  // u2_ctrl_ahb_err_stop next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_ahb_err_stop_nxt = (w_we_u2_ctrl & (|w_wmask[6])) ? ((reg_wdata[6] & w_wmask[6]) | (reg_u2_ctrl_ahb_err_stop & ~w_wmask[6])) : reg_u2_ctrl_ahb_err_stop;

  // u2_ctrl_dma_en next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_dma_en_nxt = (w_we_u2_ctrl & (|w_wmask[5])) ? ((reg_wdata[5] & w_wmask[5]) | (reg_u2_ctrl_dma_en & ~w_wmask[5])) : reg_u2_ctrl_dma_en;

  // u2_ctrl_role_ovr next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_role_ovr_nxt = (w_we_u2_ctrl & (|w_wmask[4])) ? ((reg_wdata[4] & w_wmask[4]) | (reg_u2_ctrl_role_ovr & ~w_wmask[4])) : reg_u2_ctrl_role_ovr;

  // u2_ctrl_role_ovr_en next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_role_ovr_en_nxt = (w_we_u2_ctrl & (|w_wmask[3])) ? ((reg_wdata[3] & w_wmask[3]) | (reg_u2_ctrl_role_ovr_en & ~w_wmask[3])) : reg_u2_ctrl_role_ovr_en;

  // u2_ctrl_phy_rst next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_phy_rst_nxt = (w_we_u2_ctrl & (|w_wmask[2])) ? ((reg_wdata[2] & w_wmask[2]) | (reg_u2_ctrl_phy_rst & ~w_wmask[2])) : reg_u2_ctrl_phy_rst;

  // u2_ctrl_swrst next value (rwi): software-selected byte lanes override hardware updates.
  assign w_u2_ctrl_swrst_nxt = (w_we_u2_ctrl & (|w_wmask[1])) ? ((reg_wdata[1] & w_wmask[1])
                            | ((i_hw_we_u2_ctrl_swrst ? i_hw_wdata_u2_ctrl_swrst : reg_u2_ctrl_swrst) & ~w_wmask[1]))
                          : (i_hw_we_u2_ctrl_swrst ? i_hw_wdata_u2_ctrl_swrst : reg_u2_ctrl_swrst);

  // u2_ctrl_core_en next value (rw): update only byte lanes selected by the bus strobe.
  assign w_u2_ctrl_core_en_nxt = (w_we_u2_ctrl & (|w_wmask[0])) ? ((reg_wdata[0] & w_wmask[0]) | (reg_u2_ctrl_core_en & ~w_wmask[0])) : reg_u2_ctrl_core_en;

  // Register u2_ctrl: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_u2_ctrl
    if (!w_rst_n_reg) begin
      reg_u2_ctrl_lpbk <= 1'h0;
      reg_u2_ctrl_ahb_err_stop <= 1'h1;
      reg_u2_ctrl_dma_en <= 1'h0;
      reg_u2_ctrl_role_ovr <= 1'h0;
      reg_u2_ctrl_role_ovr_en <= 1'h0;
      reg_u2_ctrl_phy_rst <= 1'h0;
      reg_u2_ctrl_swrst <= 1'h0;
      reg_u2_ctrl_core_en <= 1'h0;
    end else begin
      reg_u2_ctrl_lpbk <= w_u2_ctrl_lpbk_nxt;
      reg_u2_ctrl_ahb_err_stop <= w_u2_ctrl_ahb_err_stop_nxt;
      reg_u2_ctrl_dma_en <= w_u2_ctrl_dma_en_nxt;
      reg_u2_ctrl_role_ovr <= w_u2_ctrl_role_ovr_nxt;
      reg_u2_ctrl_role_ovr_en <= w_u2_ctrl_role_ovr_en_nxt;
      reg_u2_ctrl_phy_rst <= w_u2_ctrl_phy_rst_nxt;
      reg_u2_ctrl_swrst <= w_u2_ctrl_swrst_nxt;
      reg_u2_ctrl_core_en <= w_u2_ctrl_core_en_nxt;
    end
  end

  // Register u2_ctrl: output ports follow the flops.
  assign o_u2_ctrl_lpbk = reg_u2_ctrl_lpbk;
  assign o_u2_ctrl_ahb_err_stop = reg_u2_ctrl_ahb_err_stop;
  assign o_u2_ctrl_dma_en = reg_u2_ctrl_dma_en;
  assign o_u2_ctrl_role_ovr = reg_u2_ctrl_role_ovr;
  assign o_u2_ctrl_role_ovr_en = reg_u2_ctrl_role_ovr_en;
  assign o_u2_ctrl_phy_rst = reg_u2_ctrl_phy_rst;
  assign o_u2_ctrl_swrst = reg_u2_ctrl_swrst;
  assign o_u2_ctrl_core_en = reg_u2_ctrl_core_en;

  // Register u2_ctrl: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_u2_ctrl_value
    w_u2_ctrl_value = '0;
    w_u2_ctrl_value[7] = reg_u2_ctrl_lpbk;
    w_u2_ctrl_value[6] = reg_u2_ctrl_ahb_err_stop;
